  await figma.loadFontAsync({ family: "DM Sans", style: "Medium" });
  await figma.loadFontAsync({ family: "Reenie Beanie", style: "Regular" });

  const workspace = figma.currentPage;
  const componentsFrame = figma.createFrame();
  componentsFrame.name = "Components (My Library)";
  componentsFrame.y = -1000;
  workspace.appendChild(componentsFrame);

  // Helper to create basic button
  function createButton(text, primary = true) {
    const frame = figma.createFrame();
    frame.name = "Button";
    frame.resize(327, 50);
    frame.cornerRadius = 25;
    frame.fills = [{ type: 'SOLID', color: primary ? { r: 50/255, g: 74/255, b: 89/255 } : { r: 245/255, g: 245/255, b: 245/255 } }];
    frame.layoutMode = 'HORIZONTAL';
    frame.primaryAxisAlignItems = 'CENTER';
    frame.counterAxisAlignItems = 'CENTER';

    const textNode = figma.createText();
    textNode.fontName = { family: "Poppins", style: "SemiBold" };
    textNode.characters = text;
    textNode.fills = [{ type: 'SOLID', color: primary ? { r: 1, g: 1, b: 1 } : { r: 50/255, g: 74/255, b: 89/255 } }];
    frame.appendChild(textNode);
    return frame;
  }

  // Create component set
  const button = createButton("Next");
  const comp = figma.createComponent();
  comp.name = "ButtonComponent";
  comp.appendChild(button);
  componentsFrame.appendChild(comp);

  return { status: "Components created" };
})();

