(async () => {
  const mediaPage = figma.root.children.find(p => p.name.includes("04 · Media"));
  const mediaNodes = mediaPage.findAll(n => n.type === 'INSTANCE' || n.type === 'COMPONENT');

  const getAsset = (name) => mediaNodes.find(n => n.name === name);

  // Example: Clone logo and place it on 01_Welcome
  const welcomeFrame = figma.currentPage.children.find(f => f.name === "01_Welcome");
  const logo = getAsset("Logo_Magic_Coffee");
  if (logo) {
    const logoInstance = logo.clone();
    logoInstance.x = 150;
    logoInstance.y = 100;
    welcomeFrame.appendChild(logoInstance);
  }

  return { status: "Assets cloned" };
})();

